using System.IO.Abstractions;

namespace MyApp.Services;

/// <summary>
/// A delegating wrapper around <see cref="IFileSystem"/>.
/// Override individual members to add custom behavior (logging, caching, etc.).
/// </summary>
public class FileSystemWrapper(IFileSystem inner) : IFileSystem
{
    protected IFileSystem Inner { get; } = inner;

    public virtual IDirectory Directory => Inner.Directory;

    public virtual IDirectoryInfoFactory DirectoryInfo => Inner.DirectoryInfo;

    public virtual IDriveInfoFactory DriveInfo => Inner.DriveInfo;

    public virtual IFile File => Inner.File;

    public virtual IFileInfoFactory FileInfo => Inner.FileInfo;

    public virtual IFileStreamFactory FileStream => Inner.FileStream;

    public virtual IFileSystemWatcherFactory FileSystemWatcher => Inner.FileSystemWatcher;

    public virtual IPath Path => Inner.Path;
}

